import json

path = '/home/mi/.kiro/sessions/5797b216f4c7e8b1/sess_b511c05d-7162-44af-bc58-f3ba3c6d682d/messages.jsonl'

seen = {}
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        t = d.get('payload', {}).get('type')
        if t in ('user', 'assistant', 'tool_call', 'tool_result') and t not in seen:
            seen[t] = d
        if len(seen) == 4:
            break

for t, d in seen.items():
    print("=" * 20, t, "=" * 20)
    print(json.dumps(d, ensure_ascii=False, indent=2)[:2000])
    print()
